/* ident.js v5 —— 首页片头：透明浮景双视频 ident + 双联图叙事节点（M69）
   亮=女生（坐→躺→描云）·暗=男生（朝右行走→弯腰看水面）；片尾含 1.4s 冻结定格。
   双联图（昼|夜背靠背）双用途：
     · seam  = 每循环片尾定格卡：video 冻结尾 → 双联淡入 hold 1.4s → 淡出+视频回 0（循环缝合点）
     · bridge = 主题转场桥：旧视频 → 双联（两世界之门）→ 新视频
   reduced-motion = poster 静帧，无循环无 duo。点击舞台=重播。
   调试钩子 window.__ident.phase() → 'play' | 'seam' | 'bridge'。 */
const POSTER_LIGHT = "data:image/jpeg;base64,";
const POSTER_DARK = "data:image/jpeg;base64,";
window.DCIdent = {
  build() {
    return `
  <div class="idf-halo" data-k="light" style="background-image:url(${POSTER_LIGHT})"></div>
  <div class="idf-halo" data-k="dark" style="background-image:url(${POSTER_DARK})"></div>
  <video class="idf-video" data-k="light" src="assets/ident-light.ffdc4887.mp4" poster="${POSTER_LIGHT}" muted playsinline preload="none" tabindex="-1"></video>
  <video class="idf-video" data-k="dark" src="assets/ident-dark.bc4c173a.mp4" poster="${POSTER_DARK}" muted playsinline preload="none" tabindex="-1"></video>
  <div class="idf-duo" data-duo-bg="assets/logo-main.png"></div>`; // M76-W8: duo 背景懒挂（2MB 图不抢视频连接）
  },
  wire(el) {
    const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const vids = { light: el.querySelector('.idf-video[data-k="light"]'), dark: el.querySelector('.idf-video[data-k="dark"]') };
    const halos = { light: el.querySelector('.idf-halo[data-k="light"]'), dark: el.querySelector('.idf-halo[data-k="dark"]') };
    let cur = document.documentElement.dataset.theme === "dark" ? "dark" : "light";
    vids[cur].preload = "auto"; // M76-W8: boot 即排队当前主题视频，抢在 stalled 大图前
    let phase = "play";
    let busy = false;
    const setPhase = (p) => { phase = p; };
    window.__ident = { phase: () => phase };

    const playVid = (k) => { vids[k].currentTime = 0; const pr = vids[k].play(); if (pr && pr.catch) pr.catch(() => {}); };

    const seam = (k) => {
      if (busy || reduced) return;
      busy = true; setPhase("seam");
      el.classList.add("duo");
      setTimeout(() => {
        el.classList.remove("duo");
        playVid(k);
        setPhase("play");
        busy = false;
      }, 1900); // .5s 淡入 + 1.4s 定格
    };

    vids.light.addEventListener("ended", () => { if (cur === "light") seam("light"); });
    vids.dark.addEventListener("ended", () => { if (cur === "dark") seam("dark"); });

    const setActive = (theme, restart) => {
      if (theme === cur && !restart) return;
      const prev = cur;
      cur = theme;
      if (reduced) {
        for (const k of ["light", "dark"]) {
          vids[k].classList.toggle("on", k === theme);
          halos[k].classList.toggle("on", k === theme);
          vids[k].pause(); vids[k].currentTime = 0;
        }
        return;
      }
      if (prev !== theme) {
        // bridge：旧视频 → 双联 → 新视频
        setPhase("bridge");
        el.classList.add("duo");
        vids[prev].classList.remove("on");
        setTimeout(() => {
          vids[theme].classList.add("on");
          halos[theme].classList.add("on");
          halos[prev].classList.remove("on");
          playVid(theme);
          setTimeout(() => { el.classList.remove("duo"); setPhase("play"); }, 420);
        }, 430);
      } else if (restart) {
        vids[theme].preload = "auto";
        playVid(theme);
      }
      for (const k of ["light", "dark"]) {
        vids[k].classList.toggle("on", k === theme);
        halos[k].classList.toggle("on", k === theme);
        if (k !== theme) setTimeout(() => { if (cur !== k) vids[k].pause(); }, 900);
      }
    };

    el.onclick = () => {
      if (reduced || busy || phase !== "play") return;
      el.classList.add("duo");
      setPhase("seam");
      setTimeout(() => { el.classList.remove("duo"); playVid(cur); setPhase("play"); }, 500);
    };

    // M76-W8: 播放不依赖 window.load（Pages 边缘偶发 stall 会拖住 load → 视频永不启动）；
    // DOMContentLoaded+300ms 即启动，看门狗 ≤4 次重试 play()；poster halo 兜底视觉
    const duoEl = el.querySelector(".idf-duo");
    const attachDuo = () => { if (duoEl && !duoEl.style.backgroundImage) duoEl.style.backgroundImage = `url(${duoEl.getAttribute("data-duo-bg")})`; };
    vids.light.addEventListener("timeupdate", function t() { if (vids.light.currentTime > 10) { attachDuo(); vids.light.removeEventListener("timeupdate", t); } });
    vids.light.addEventListener("ended", attachDuo, { once: true });
    let started = false;
    const start = () => { if (started) return; started = true; setActive(cur, true); watchdog(0); };
    const watchdog = (n) => {
      if (n > 3) return;
      setTimeout(() => {
        const v = vids[cur];
        if (v && (v.readyState < 3 || v.paused) && phase === "play" && !reduced) {
          v.preload = "auto";
          const pr = v.play(); if (pr && pr.catch) pr.catch(() => {});
          watchdog(n + 1);
        }
      }, 900);
    };
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", () => setTimeout(start, 300), { once: true });
    else setTimeout(start, 300);
    return { swap: (theme) => setActive(theme, false), phase: () => phase };
  },
};

// M76-W8f: 元素级自愈引导——任何重建/闭包失配/连接 stall 后仍能把当前主题视频拉起来
(function identSelfHeal() {
  const RM = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (RM) return;
  let tries = 0;
  const tick = () => {
    tries++;
    const theme = document.documentElement.dataset.theme === "dark" ? "dark" : "light";
    const v = document.querySelector(`.idf-video[data-k="${theme}"]`);
    if (v) {
      if (v.preload === "none") v.preload = "auto";
      if (v.readyState >= 2 && v.paused && v.classList.contains("on")) { const pr = v.play(); if (pr && pr.catch) pr.catch(() => {}); }
    }
    if (tries < 14) setTimeout(tick, 800);
  };
  setTimeout(tick, 600);
})();
